function legacyBookingSections(){const week=db.bookings.filter(b=>b.day>=today()&&b.day<=addDay(today(),6)&&b.status!=='draft').sort((a,b)=>(a.day+time(a.start)).localeCompare(b.day+time(b.start)));const outsideWeek=db.bookings.filter(b=>isOpenBooking(b)&&!week.includes(b)).sort((a,b)=>a.day.localeCompare(b.day)||a.start-b.start);const rows=items=>items.map(b=>'<div class="record"><span class="badge">'+stateLabel[b.status]+'</span><h3>'+esc(b.name)+' · '+esc(b.title)+'</h3><p>'+b.day+' '+time(b.start)+'–'+time(b.start+b.duration)+' · '+esc(db.staffSchedule?.staff.find(s=>s.id===b.staffId)?.name||'待分配')+'</p>'+ '<p>联系电话 '+bookingContactLink(b)+'</p>'+lifecycleButtons(b)+'</div>').join('')||'<div class="empty">暂无预约。</div>';return '<div class="view-title"><h1>预约与服务进度</h1></div><section class="card"><h2>今天</h2>'+rows(week.filter(b=>b.day===today()))+'</section><section class="card"><h2>本周</h2>'+rows(week)+'</section>'+(outsideWeek.length?'<section class="card"><h2>其他日期待处理预约</h2>'+rows(outsideWeek)+'</section>':'');}
