if(a==='queue-state'){if(v==='called'&&db.queue.some(q=>q.day===today()&&q.status==='called'))return toast('请先处理已叫号客户');db.queue.find(x=>x.id===id).status=v;save();render();return;}
if(a==='start-queue'){const q=db.queue.find(x=>x.id===id),raw=prompt('预计占用多少分钟？项目由店主现场确定。','30');if(raw===null)return;const dur=Number(raw);if(!Number.isInteger(dur)||dur<5||dur>480)return toast('请输入 5–480 分钟');const start=currentMinute(),end=start+dur;if(end>1440)return toast('不可跨天');if(occupied(today()).some(x=>start<x.end&&end>x.start))return toast('与已有时间占用冲突，请先协调');const bid=uid();db.blocks.push({id:bid,day:today(),start,end,reason:q.number+'现场服务'});q.status='serving';q.block=bid;save();render();toast('已开始服务，线上空位同步更新');return;}
if(a==='finish-queue'){const q=db.queue.find(x=>x.id===id);q.status='done';const block=db.blocks.find(x=>x.id===q.block);if(block)block.removed=true;save();render();return;}
