document.addEventListener('click',e=>{const b=e.target.closest('[data-action="calendar-empty"]');if(!b)return;const draft={id:uid(),client:'merchant',name:'',title:'洗剪吹',project:'cut',day:b.dataset.day,start:+b.dataset.start,duration:db.settings.medium,end:+b.dataset.start+db.settings.medium,status:'draft',created:Date.now()};db.bookings.push(draft);openBookingEditor(draft.id,true);});
const originalMerchantAnswer=merchantAnswer;merchantAnswer=function(text){const base=today(),parts=base.split('-').map(Number),dayMatch=text.match(/(\d{1,2})\s*号/);let d=/今天/.test(text)?base:/明天/.test(text)?addDay(base,1):/后天/.test(text)?addDay(base,2):dayMatch?parts[0]+'-'+String(parts[1]).padStart(2,'0')+'-'+String(+dayMatch[1]).padStart(2,'0'):'';if(dayMatch&&d<base)d=(parts[0]+1)+'-'+String(parts[1]).padStart(2,'0')+'-'+String(+dayMatch[1]).padStart(2,'0');db.staffSchedule=db.staffSchedule||{staff:[],closures:[]};db.staffSchedule.closures=db.staffSchedule.closures||[];const meal=/午餐|中午吃饭|午休/.test(text)?[db.settings.lunchStart,db.settings.lunchEnd]:/晚餐|晚上吃饭|晚饭/.test(text)?[db.settings.dinnerStart,db.settings.dinnerEnd]:null;if(d&&(/休息|吃饭|用餐|暂停/.test(text))&&!/预约|洗剪吹|剪发|理发/.test(text)){if(meal&&meal[0]<meal[1]){db.blocks.push({id:uid(),day:d,start:meal[0],end:meal[1],reason:'休息'});db.merchantMessages=db.merchantMessages||[];db.merchantMessages.push({role:'user',text},{role:'assistant',text:'已设置 '+d+' '+time(meal[0])+'–'+time(meal[1])+' 为休息，日程已更新。'});save();render();toast('休息时段已加入日程');return;}if(!db.staffSchedule.closures.some(x=>x.day===d))db.staffSchedule.closures.push({day:d,reason:'休息'});db.merchantMessages=db.merchantMessages||[];db.merchantMessages.push({role:'user',text},{role:'assistant',text:'已设置 '+d+' 全天休息，日程已更新。'});save();render();toast('休息日已加入日程');return;}const tm=text.match(/(?:下午|晚上|上午)?\s*(\d{1,2})\s*[点时:：](\d{0,2})/);const isCut=/洗剪吹|剪发|剪头|理发|预约|染发|染色|染头|烫发/.test(text);if(d&&tm&&isCut){const h=(/(下午|晚上)/.test(tm[0])&&+tm[1]<12?+tm[1]+12:+tm[1]),st=h*60+(+(tm[2]||0)),name=(text.match(/(?:给|为|客户)\s*([\u4e00-\u9fa5]{1,6})/)||text.match(/号([\u4e00-\u9fa5]{1,5}?)(?:从|在|于)/)||text.match(/点(?:\d+分)?([\u4e00-\u9fa5]{1,5}?)(?:染|烫|剪|做|预约)/)||text.match(/号([\u4e00-\u9fa5]{1,5})/)||[])[1]||'待填写客户',pm=text.match(/(\d+(?:\.\d+)?)\s*(小时|时|分钟)/),dur=pm?(pm[2]==='分钟'?Math.round(+pm[1]):Math.round(+pm[1]*60)):(/染发|染色|染头|烫发/.test(text)?120:db.settings.medium),title=/染发|染色|染头/.test(text)?'染发':/烫发/.test(text)?'烫发':'洗剪吹',project=title==='染发'?'color':title==='烫发'?'perm':'cut';if(!canBook(d,st,dur)){db.merchantMessages=db.merchantMessages||[];db.merchantMessages.push({role:'user',text},{role:'assistant',text:'这段时间当前无法安排，可能已过营业时间、与休息时段或已有预约冲突。请换一个时间。'});save();render();toast('该时间段不可安排');return;}const order={id:uid(),client:'merchant',name,title,project,day:d,start:st,duration:dur,end:st+dur,status:'confirmed',price:'待确认',deposit:'不收定金',notes:text,created:Date.now()};assignStaff(order);db.bookings.push(order);db.merchantMessages=db.merchantMessages||[];db.merchantMessages.push({role:'user',text},{role:'assistant',text:'已识别并加入日程：'+d+' '+time(st)+'，'+name+'，'+title+'，'+dur+' 分钟。'});save();render();toast('已识别并加入日程');return;}originalMerchantAnswer(text);};
